import type { UserDomainMediaConfig } from './../../ricos-types/index.js';

import { WIX_MEDIA_BASE_URL } from './media-url-consts.js';

const WIX_MEDIA_IMAGE_PREFIX = `${WIX_MEDIA_BASE_URL}media/`;

/**
 * Swaps wixstatic's media host for the site's domain only when the image URI
 * belongs to one of the site's configured media prefixes.
 */
export const applyUserDomainMedia = (
  url: string,
  userDomainMedia?: UserDomainMediaConfig
): string => {
  const { baseUrl, prefixes = [] } = userDomainMedia ?? {};
  if (!baseUrl || !url.startsWith(WIX_MEDIA_IMAGE_PREFIX)) {
    return url;
  }

  const uri = url.slice(WIX_MEDIA_IMAGE_PREFIX.length);
  return prefixes.some(prefix => uri.startsWith(`${prefix}_`))
    ? `${baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`}${uri}`
    : url;
};
