import type { PluginContainerData } from './../../ricos-schema/next-schema/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const getNodeTextWrap: Resolver<PluginContainerData['textWrap'] | undefined> = (
  _,
  __,
  editor
) => {
  const node = (editor?.state?.selection as Record<string, any> | undefined)?.node;
  if (node) {
    return node.attrs?.containerData?.textWrap;
  }
  return undefined;
};
