import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import { ModalDesktop } from './modal-desktop.js';
import { ModalMobile } from './modal-mobile.js';
import type { LinkModalProps } from './types.js';

export const LinkModal: React.FC<LinkModalProps> = props => {
  const { isMobile } = useContext(RicosContext);

  return isMobile ? <ModalMobile {...props} /> : <ModalDesktop {...props} />;
};
