import { isSSR } from '../is-ssr.js';
import type {
  MediaManagerMediaType,
  SDKAudioMedia,
  SDKFileMedia,
  SDKImageMedia,
  SDKVideoMedia,
} from './types.js';

export interface EditorMediaPanelOptions {
  mediaType?: MediaManagerMediaType;
  isMultiSelect?: boolean;
}
interface BMMediaPanelOptions {
  multiSelect?: boolean;
  onSuccess?: (data: $TSFixMe) => void;
  onCancel?: () => void;
}

interface BMMediaSDK {
  invoke(
    name: string,
    mediaType: MediaManagerMediaType,
    appDefId: string,
    options: BMMediaPanelOptions
  ): void;
  registeredMethods?: {
    ['mediaManager.open']?: any;
  };
}

interface EditorMediaSDK {
  editor: {
    openMediaPanel: (token?: string, options?: EditorMediaPanelOptions) => Promise<any>;
  };
}

declare global {
  interface Window {
    ModuleRegistry?: BMMediaSDK;
    editorSDK?: EditorMediaSDK;
  }
}

export interface ExternalModalNotifier {
  notifyExternalModalOpened: () => void;
  notifyExternalModalClosed: () => void;
}

export const createOpenMediaManagerFn = (
  modals: ExternalModalNotifier
): OpenMediaManagerFn | undefined => {
  if (isSSR()) {
    return undefined;
  }
  const mediaManagerInstance = window.editorSDK || window.ModuleRegistry;
  const isInEditor = mediaManagerInstance && 'editor' in mediaManagerInstance;
  const isInBM =
    mediaManagerInstance &&
    'registeredMethods' in mediaManagerInstance &&
    mediaManagerInstance.registeredMethods &&
    typeof mediaManagerInstance.registeredMethods === 'object' &&
    'mediaManager.open' in mediaManagerInstance.registeredMethods;

  if (!mediaManagerInstance || (!isInEditor && !isInBM)) {
    return undefined;
  }

  return async ({ mediaType, isMultiSelect, appDefId }) => {
    modals.notifyExternalModalOpened();
    try {
      return await ('editor' in mediaManagerInstance
        ? mediaManagerInstance.editor.openMediaPanel('', {
            mediaType,
            isMultiSelect,
          })
        : new Promise((resolve, reject) => {
            mediaManagerInstance.invoke('mediaManager.open', mediaType, appDefId || 'ricos', {
              multiSelect: isMultiSelect,
              onSuccess: data => resolve(data.items),
              onCancel: reject,
            });
          }));
    } finally {
      // Cancellation also flows through this path (invoke's onCancel
      // rejects, openMediaPanel's promise rejects) — notify unconditionally
      // so the plugin toolbar's dismiss suppression never gets stuck on.
      modals.notifyExternalModalClosed();
    }
  };
};

type OpenOptions<M extends MediaManagerMediaType> = {
  mediaType: M;
  isMultiSelect?: boolean;
  appDefId?: string;
};

type OpenMediaManagerFn = {
  (options: OpenOptions<MediaManagerMediaType.ALL_MEDIA>): Promise<SDKFileMedia[]>;
  (options: OpenOptions<MediaManagerMediaType.IMAGE>): Promise<SDKImageMedia[]>;
  (options: OpenOptions<MediaManagerMediaType.VIDEO>): Promise<SDKVideoMedia[]>;
  (options: OpenOptions<MediaManagerMediaType.AUDIO>): Promise<SDKAudioMedia[]>;
};
