import { useContext, useMemo } from 'react';

import { DevContext } from './../../../ricos-context/dev-context.js';
import { type RequestService } from './../../request-service-provider/request-service-provider.js';
import { useRequestService } from './../../request-service-provider/request-service-provider.js';

import type { ItemsResponseBody } from '../serverless-types/serverless-types.js';
import type {
  FetchSitePages,
  FetchSitePagesParams,
  SitePagesItem,
  SitePagesPageType,
} from '../types.js';

const pageTypePaths: Record<SitePagesPageType, string> = {
  blogPost: 'blog-posts',
  staticPage: 'static-pages',
  dynamicPage: 'dynamic-all-pages',
  dynamicItemPage: 'dynamic-item-pages',
  storeProduct: 'stores-products',
  storeCatalog: 'stores-catalogs',
};

export const useFetchSitePages = (): FetchSitePages => {
  const { makeRequest } = useRequestService();
  const fetchSitePages = useMemo<FetchSitePages>(
    () => (pageType, params) =>
      (async (
        makeRequest: RequestService['makeRequest'],
        pageType: SitePagesPageType,
        params: FetchSitePagesParams
      ): Promise<ItemsResponseBody> => {
        const response = await makeRequest(`/_api/ricos-site-pages/${pageTypePaths[pageType]}`, {
          body: JSON.stringify(params),
          headers: {
            'Content-Type': 'application/json',
          },
          method: 'POST',
        });

        const result = await response.json();
        return {
          ...result,
          items:
            result.items.map((item: SitePagesItem) => ({
              ...item,
              updatedDate: item.updatedDate ? new Date(item.updatedDate) : undefined,
            })) || [],
        };
      })(makeRequest, pageType, params),
    [makeRequest]
  );

  return useContext(DevContext)?.fetchSitePages || fetchSitePages;
};
