import type { LinkOptions } from './../link-modal/open-link-modal/types.js';
import { DEFAULT_LINK_VALUE } from './../link/constants.js';
import type { NamedLink } from './../link/types.js';

import { deepMerge } from '../deep-merge.js';

export const getInitialLinkData = (options?: LinkOptions): NamedLink => {
  if (!options) {
    return DEFAULT_LINK_VALUE;
  }
  const { target, nofollow, sponsored, noreferrer } = options;
  const rel = {
    ...(nofollow === undefined ? {} : { nofollow }),
    ...(sponsored === undefined ? {} : { sponsored }),
    ...(noreferrer === undefined ? {} : { noreferrer }),
  };
  return deepMerge({}, DEFAULT_LINK_VALUE, {
    ...(target ? { target } : {}),
    ...(Object.keys(rel).some(key => rel[key as keyof typeof rel] !== undefined) ? { rel } : {}),
  });
};
