import { useEffect, useMemo, useState } from 'react';

import { useSitePagesFetchContext } from './../../../site-pages/site-pages-fetch-context.js';
import type { SitePagesItem, SitePagesPageType } from './../../../site-pages/types.js';
import { unreachable } from './../../../uncreachable.js';

type HookResult = {
  areAllFetched: boolean;
  error?: any;
  hasMore?: boolean;
  isLoading: boolean;
  items: SitePagesItem[];
  loadMore?: () => void;
  query: string;
  setQuery: (query: string) => void;
};

const areAllFetched = (
  fetchQuery: string,
  fetchState: ReturnType<typeof useSitePagesFetchContext>['fetchState'],
  loadMore: (() => void) | undefined
) => fetchQuery === '' && fetchState.type === 'ready' && !loadMore;

const search = (query: string, items: SitePagesItem[]) =>
  items.filter(item => item.title.toLowerCase().includes(query.trim().toLowerCase()));

export const useSitePages = (pageType: SitePagesPageType, itemPagePrefix?: string): HookResult => {
  const [query, setQuery] = useState<string>('');
  const [fetchQuery, setFetchQuery] = useState<string>(query);
  const { fetchState, loadMore } = useSitePagesFetchContext(pageType, fetchQuery, itemPagePrefix);

  const items: SitePagesItem[] = useMemo(
    () => ('items' in fetchState ? search(query, fetchState.items) : []),
    [fetchQuery, fetchState, !!loadMore, query]
  );

  useEffect(() => {
    const skipChange =
      fetchQuery === query ||
      fetchState.type === 'loading' ||
      (fetchQuery === '' && fetchState.type === 'loading-error') ||
      areAllFetched(fetchQuery, fetchState, loadMore);
    if (!skipChange) {
      setFetchQuery(query);
    }
  }, [fetchQuery, fetchState, !!loadMore, query]);

  const result = {
    items,
    query,
    setQuery,
  };

  switch (fetchState.type) {
    case 'loading':
    case 'loading-more':
      return {
        ...result,
        areAllFetched: false,
        isLoading: true,
      };
    case 'loading-error':
      return {
        ...result,
        areAllFetched: false,
        error: fetchState.error,
        isLoading: false,
      };
    case 'ready':
      if (areAllFetched(fetchQuery, fetchState, loadMore)) {
        return {
          ...result,
          areAllFetched: true,
          hasMore: false,
          isLoading: false,
        };
      } else if (loadMore) {
        return {
          ...result,
          areAllFetched: false,
          error: fetchState.error,
          hasMore: true,
          isLoading: false,
          loadMore,
        };
      } else {
        return {
          ...result,
          areAllFetched: false,
          error: fetchState.error,
          hasMore: false,
          isLoading: false,
        };
      }
    default:
      unreachable(fetchState);
      return {} as HookResult;
  }
};
