/* oxlint-disable jsx-a11y/no-autofocus */
import {
  Dropdown,
  type DropdownLayoutValueOption,
  FormField,
  type PopoverProps,
  listItemSelectBuilder,
} from '@wix/design-system';
import React, { useMemo } from 'react';

import type { TFunction } from './../../../ricos-types/common-types.js';
import { useBiNext } from './../../bi-context-provider/bi-context-provider.js';
import type { FetchState } from './../../site-pages/site-pages-fetch-context.js';
import { isDefined } from './../../../wix-rich-content-common/index.js';

import { LINK_MODAL_ID } from '../constants.js';
import { LINK_TYPE } from '../data-hooks/data-hooks.js';
import type { LinkType } from './types.js';

type Props = {
  autoFocus: boolean;
  dropDownPopoverProps?: PopoverProps;
  onSelect: (type: LinkType) => void;
  showSitePages: boolean;
  t: TFunction;
  type: string;
  enabledLinkTypes?: LinkType[];
  cache?: Cache;
};
type Cache = Record<string, FetchState>;

type Option = DropdownLayoutValueOption & { id: LinkType; size: string };

const translationTypes: Record<LinkType, string> = {
  blogPost: 'BlogPost',
  section: 'Section',
  staticPage: 'StaticPage',
  dynamicPage: 'DynamicPage',
  storeProduct: 'StoreProduct',
  storeCatalog: 'StoreCatalog',
  'web-address': 'WebAddress',
};

const configToOption = (t: TFunction, linkType: LinkType) =>
  listItemSelectBuilder({
    id: linkType,
    label: t(`LinkSettings_TypeSelect_Option_${translationTypes[linkType]}`),
    size: 'small',
    title: t(`LinkSettings_TypeSelect_Option_${translationTypes[linkType]}`),
  }) as Option;

const defaultOptions: LinkType[] = ['web-address', 'section'];

export const TypeSelect: React.FC<Props> = ({
  autoFocus,
  dropDownPopoverProps,
  onSelect,
  showSitePages,
  t,
  type,
  enabledLinkTypes,
  cache,
}) => {
  const logBi = useBiNext({ pluginId: 'link', modalId: LINK_MODAL_ID });

  const options = useMemo(() => {
    const availableLinkTypes: LinkType[] = [
      ...defaultOptions,
      cache?.staticPage?.type === 'ready' && cache?.staticPage?.items?.length > 0
        ? ('staticPage' as const)
        : undefined,
      cache?.blogPost?.type === 'ready' && cache?.blogPost?.items?.length > 0
        ? ('blogPost' as const)
        : undefined,
      cache?.dynamicPage?.type === 'ready' && cache?.dynamicPage?.items?.length > 0
        ? ('dynamicPage' as const)
        : undefined,
      cache?.storeProduct?.type === 'ready' && cache?.storeProduct?.items?.length > 0
        ? ('storeProduct' as const)
        : undefined,
      cache?.storeCatalog?.type === 'ready' && cache?.storeCatalog?.items?.length > 0
        ? ('storeCatalog' as const)
        : undefined,
    ]
      .filter(isDefined)
      .filter(linkType => (enabledLinkTypes?.length ? enabledLinkTypes.includes(linkType) : true));
    return availableLinkTypes.map(linkType => configToOption(t, linkType));
  }, [
    showSitePages,
    t,
    enabledLinkTypes,
    cache?.staticPage?.type,
    cache?.blogPost?.type,
    cache?.dynamicPage?.type,
    cache?.storeProduct?.type,
    cache?.storeCatalog?.type,
  ]);

  const onOptionsShow = () => {
    logBi({ dataHook: LINK_TYPE });
  };

  const onSelectOption = (option: DropdownLayoutValueOption) => {
    onSelect((option as Option).id);
    logBi({ dataHook: LINK_TYPE, value: (option as Option).id });
  };

  return (
    <FormField label={t('LinkSettings_TypeSelect_Label')} labelPlacement="top">
      <Dropdown
        autoFocus={autoFocus}
        dataHook={LINK_TYPE}
        onOptionsShow={onOptionsShow}
        onSelect={onSelectOption}
        options={options}
        popoverProps={dropDownPopoverProps}
        selectedId={type}
        size="small"
        valueParser={option => option.label}
        hasMore
        infiniteScroll={[
          cache?.staticPage,
          cache?.blogPost,
          cache?.dynamicPage,
          cache?.storeProduct,
          cache?.storeCatalog,
        ].some(state => state && state.type === 'loading')}
      />
    </FormField>
  );
};
